CREATE FUNCTION public.voorraad_daggrens(p_datum date,p_moment text) RETURNS date LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT p_datum+CASE WHEN p_moment='na_sluiting' THEN 1 ELSE 0 END $$;
CREATE FUNCTION public.voorraad_teldeadline(p_nu timestamptz) RETURNS date LANGUAGE sql STABLE SET search_path=public AS $$ WITH n AS(SELECT p_nu AT TIME ZONE 'Europe/Amsterdam' d),w AS(SELECT d,d::date-((extract(isodow FROM d)::int-3+7)%7) woensdag FROM n) SELECT woensdag-CASE WHEN d<woensdag+time '06:00' THEN 7 ELSE 0 END FROM w $$;
CREATE FUNCTION public.voorraad_hertellen_nodig(p_totaal numeric,p_stand numeric) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT p_stand IS NOT NULL AND abs(p_totaal-p_stand)>greatest(abs(p_stand)*0.20,2) $$;
CREATE FUNCTION public.voorraad_bewegingen_lezen(p_vestiging text) RETURNS TABLE(voorraad_artikel_id uuid,vestiging text,datum date,soort text,hoeveelheid numeric,bron_ref text,bronkwaliteit text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
IF NOT public.is_service_call() AND NOT public.heeft_vestiging(auth.uid(),p_vestiging) THEN RAISE EXCEPTION 'Geen vestigingstoegang' USING ERRCODE='42501'; END IF;
RETURN QUERY WITH hist_match AS(SELECT a.id aid,h.*,k.factor,count(*) OVER(PARTITION BY h.id) matches FROM public.bestel_historie_import h JOIN public.voorraad_artikel a ON a.vestiging=h.vestiging JOIN public.voorraad_ontvangst_koppeling k ON k.voorraad_artikel_id=a.id WHERE h.vestiging=p_vestiging AND h.leverancier_naam_ruw ILIKE k.leverancier_naam AND h.artikel_naam_ruw ~* k.naam_patroon AND (k.uitsluit_patroon IS NULL OR h.artikel_naam_ruw !~* k.uitsluit_patroon)),
bord_match AS(SELECT a.id aid,b.*,k.factor,a.tel_eenheid,v.vorm,v.eenheid vorm_eenheid,count(*) OVER(PARTITION BY b.id) matches,(SELECT count(*) FROM public.bestel_signalen r WHERE r.restant_van=b.id) rest_count,(SELECT r.aantal FROM public.bestel_signalen r WHERE r.restant_van=b.id AND r.status='open' AND r.eenheid=b.eenheid AND r.artikel_vorm_id IS NOT DISTINCT FROM b.artikel_vorm_id AND r.vestiging=b.vestiging LIMIT 1) rest_aantal FROM public.bestel_signalen b JOIN public.voorraad_artikel a ON a.vestiging=b.vestiging JOIN public.voorraad_ontvangst_koppeling k ON k.voorraad_artikel_id=a.id AND k.artikel_id=b.artikel_id LEFT JOIN public.artikel_vormen v ON v.id=b.artikel_vorm_id AND v.vestiging=b.vestiging AND v.artikel_id=b.artikel_id LEFT JOIN public.leveranciers l ON l.id=b.leverancier_id WHERE b.vestiging=p_vestiging AND b.geleverd_op IS NOT NULL AND coalesce(l.naam,'') ILIKE k.leverancier_naam AND NOT EXISTS(SELECT 1 FROM public.bestel_historie_import h WHERE h.vestiging=b.vestiging AND nullif(trim(b.bestelreferentie),'') IS NOT NULL AND nullif(trim(h.extern_ordernummer),'')=trim(b.bestelreferentie) AND ((b.leverancier_id IS NOT NULL AND h.leverancier_id=b.leverancier_id) OR (b.leverancier_id IS NULL AND lower(h.leverancier_naam_ruw)=lower(l.naam))))),
bord_qty AS(SELECT b.*,CASE WHEN b.eenheid=b.tel_eenheid THEN 1::numeric WHEN b.eenheid='doos' AND b.vorm_eenheid='doos' AND b.vorm ~ '24[×x]' AND b.factor=24 THEN b.factor ELSE NULL END conv,CASE WHEN b.levering_status='deels' THEN CASE WHEN b.rest_count=1 AND b.rest_aantal>0 AND b.rest_aantal<b.aantal THEN b.aantal-b.rest_aantal ELSE NULL END ELSE b.aantal END qty FROM bord_match b)
SELECT h.aid,h.vestiging,h.besteldatum,'ontvangst'::text,CASE WHEN h.matches=1 THEN h.aantal*h.factor END,'hist:'||h.id,CASE WHEN h.matches=1 THEN 'besteldatum_benadering' ELSE 'onvolledig:ambigue_koppeling' END FROM hist_match h
UNION ALL SELECT b.aid,b.vestiging,(b.geleverd_op AT TIME ZONE 'Europe/Amsterdam')::date,'ontvangst',CASE WHEN b.matches=1 THEN b.qty*b.conv END,'bord:'||b.id,CASE WHEN b.matches<>1 THEN 'onvolledig:ambigue_koppeling' WHEN b.qty IS NULL THEN 'onvolledig:deellevering' WHEN b.conv IS NULL THEN 'onvolledig:conversie' ELSE 'geleverd' END FROM bord_qty b
UNION ALL SELECT a.id,a.vestiging,c.datum,'kassa',CASE WHEN (SELECT count(*) FROM public.voorraad_verbruik_koppeling kk JOIN public.voorraad_artikel aa ON aa.id=kk.voorraad_artikel_id WHERE aa.vestiging=a.vestiging AND kk.lightspeed_product_id=c.lightspeed_product_id)=1 THEN -c.aantal*k.factor END,'kassa:'||a.vestiging||':'||c.datum||':'||c.lightspeed_product_id,CASE WHEN (SELECT count(*) FROM public.voorraad_verbruik_koppeling kk JOIN public.voorraad_artikel aa ON aa.id=kk.voorraad_artikel_id WHERE aa.vestiging=a.vestiging AND kk.lightspeed_product_id=c.lightspeed_product_id)=1 THEN 'werkdag_0600' ELSE 'onvolledig:ambigue_kassa' END FROM public.kassa_verkoop_dag c JOIN public.voorraad_artikel a ON a.vestiging=c.vestiging JOIN public.voorraad_verbruik_koppeling k ON k.voorraad_artikel_id=a.id AND k.lightspeed_product_id=c.lightspeed_product_id WHERE a.vestiging=p_vestiging
UNION ALL SELECT a.id,a.vestiging,c.datum,'correctie',c.hoeveelheid,'corr:'||c.id,'handmatig' FROM public.voorraad_correctie c JOIN public.voorraad_artikel a ON a.id=c.voorraad_artikel_id WHERE a.vestiging=p_vestiging;
END $$;
CREATE VIEW public.v_voorraad_bewegingen WITH(security_invoker=true) AS SELECT b.* FROM(SELECT DISTINCT vestiging FROM public.voorraad_artikel)a CROSS JOIN LATERAL public.voorraad_bewegingen_lezen(a.vestiging)b;
CREATE FUNCTION public.voorraad_stand_berekenen(p_artikel uuid,p_tot date,p_exclusief uuid DEFAULT NULL) RETURNS TABLE(laatste_telling_id uuid,laatste_telling date,geteld numeric,ontvangen numeric,correcties numeric,kassa numeric,opslag numeric,stand numeric,volledig boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a public.voorraad_artikel;t public.voorraad_telling;r numeric;c numeric;k numeric;o numeric;ok boolean;
BEGIN SELECT * INTO a FROM public.voorraad_artikel WHERE id=p_artikel; IF NOT FOUND THEN RETURN; END IF;
IF NOT public.is_service_call() AND NOT public.heeft_vestiging(auth.uid(),a.vestiging) THEN RAISE EXCEPTION 'Geen vestigingstoegang' USING ERRCODE='42501'; END IF;
SELECT * INTO t FROM public.voorraad_telling WHERE voorraad_artikel_id=p_artikel AND betrouwbaar AND id IS DISTINCT FROM p_exclusief AND (datum<=p_tot OR (datum=p_tot+1 AND moment='voor_opening')) ORDER BY geteld_op DESC,id DESC LIMIT 1;
IF NOT FOUND THEN RETURN QUERY SELECT NULL::uuid,NULL::date,NULL::numeric,0::numeric,0::numeric,0::numeric,0::numeric,NULL::numeric,false; RETURN; END IF;
SELECT coalesce(sum(b.hoeveelheid) FILTER(WHERE b.soort='ontvangst'),0),coalesce(sum(b.hoeveelheid) FILTER(WHERE b.soort='correctie'),0),-coalesce(sum(b.hoeveelheid) FILTER(WHERE b.soort='kassa'),0),coalesce(bool_and(b.hoeveelheid IS NOT NULL AND b.bronkwaliteit NOT LIKE 'onvolledig%'),true) INTO r,c,k,ok FROM public.voorraad_bewegingen_lezen(a.vestiging)b WHERE b.voorraad_artikel_id=p_artikel AND b.datum>=public.voorraad_daggrens(t.datum,t.moment) AND b.datum<=p_tot;
o:=k*a.verbruiksopslag_pct/100; RETURN QUERY SELECT t.id,t.datum,t.totaal,r,c,k,o,t.totaal+r+c-k-o,ok;
END $$;
CREATE VIEW public.v_voorraad_stand WITH(security_invoker=true) AS SELECT a.*,s.*,CASE WHEN s.stand IS NULL THEN 'voorraad onbekend' WHEN NOT s.volledig THEN 'onvolledig' ELSE 'berekend' END status,NOT EXISTS(SELECT 1 FROM public.voorraad_telling t WHERE t.voorraad_artikel_id=a.id AND t.betrouwbaar AND t.datum>=public.voorraad_teldeadline(now())) tellen_nodig FROM public.voorraad_artikel a CROSS JOIN LATERAL public.voorraad_stand_berekenen(a.id,(now() AT TIME ZONE 'Europe/Amsterdam')::date)s;
CREATE FUNCTION public.voorraad_telling_valideren() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a public.voorraad_artikel;p jsonb;v numeric:=0;snap numeric;ouder public.voorraad_telling;
BEGIN SELECT * INTO a FROM public.voorraad_artikel WHERE id=NEW.voorraad_artikel_id FOR UPDATE;
IF NOT public.is_service_call() AND NOT public.heeft_vestiging(auth.uid(),a.vestiging) THEN RAISE EXCEPTION 'Geen vestigingstoegang' USING ERRCODE='42501'; END IF;
IF jsonb_typeof(NEW.per_plek)<>'object' OR NEW.datum>(now() AT TIME ZONE 'Europe/Amsterdam')::date THEN RAISE EXCEPTION 'Ongeldige telling'; END IF;
IF (SELECT count(*) FROM jsonb_object_keys(NEW.per_plek))<>jsonb_array_length(a.opslagplekken) THEN RAISE EXCEPTION 'Alle plekken invullen'; END IF;
FOR p IN SELECT * FROM jsonb_array_elements(a.opslagplekken) LOOP IF jsonb_typeof(NEW.per_plek->(p->>'naam')) IS DISTINCT FROM 'number' OR (NEW.per_plek->>(p->>'naam'))::numeric<0 THEN RAISE EXCEPTION 'Alle plekken positief of nul invullen'; END IF;v:=v+(NEW.per_plek->>(p->>'naam'))::numeric*(p->>'factor')::numeric;END LOOP;
IF NEW.totaal<>v THEN RAISE EXCEPTION 'Totaal klopt niet met plekken'; END IF;
SELECT s.stand INTO snap FROM public.voorraad_stand_berekenen(a.id,public.voorraad_daggrens(NEW.datum,NEW.moment)-1,NEW.id)s;
IF NEW.hertelling_van IS NOT NULL THEN SELECT * INTO ouder FROM public.voorraad_telling WHERE id=NEW.hertelling_van;IF NOT FOUND OR ouder.voorraad_artikel_id<>a.id OR ouder.betrouwbaar OR ouder.hertelling_van IS NOT NULL OR ouder.datum<>NEW.datum OR ouder.moment<>NEW.moment OR EXISTS(SELECT 1 FROM public.voorraad_telling WHERE hertelling_van=ouder.id) THEN RAISE EXCEPTION 'Ongeldige hertelling';END IF;NEW.betrouwbaar:=true;NEW.berekend_op_moment:=ouder.berekend_op_moment;ELSE NEW.berekend_op_moment:=snap;NEW.betrouwbaar:=NOT public.voorraad_hertellen_nodig(v,snap);END IF;
NEW.geteld_door:=auth.uid();NEW.geteld_op:=clock_timestamp();RETURN NEW;END $$;
CREATE TRIGGER voorraad_telling_valideren BEFORE INSERT ON public.voorraad_telling FOR EACH ROW EXECUTE FUNCTION public.voorraad_telling_valideren();
CREATE FUNCTION public.voorraad_relatie_valideren() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.voorraad_artikel_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.voorraad_artikel WHERE id=NEW.voorraad_artikel_id AND vestiging=NEW.vestiging) THEN RAISE EXCEPTION 'Proefartikel hoort bij andere vestiging'; END IF;IF TG_TABLE_NAME='leer_voorstel' AND TG_OP='UPDATE' AND NOT public.is_service_call() THEN NEW.beoordeeld_door:=auth.uid();NEW.beoordeeld_op:=now();END IF;RETURN NEW;END $$;
CREATE TRIGGER advies_log_vestiging BEFORE INSERT OR UPDATE ON public.advies_log FOR EACH ROW EXECUTE FUNCTION public.voorraad_relatie_valideren();
CREATE TRIGGER leer_voorstel_vestiging BEFORE INSERT OR UPDATE ON public.leer_voorstel FOR EACH ROW EXECUTE FUNCTION public.voorraad_relatie_valideren();
REVOKE ALL ON FUNCTION public.voorraad_daggrens(date,text),public.voorraad_teldeadline(timestamptz),public.voorraad_hertellen_nodig(numeric,numeric) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.voorraad_daggrens(date,text),public.voorraad_teldeadline(timestamptz),public.voorraad_hertellen_nodig(numeric,numeric) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.voorraad_bewegingen_lezen(text),public.voorraad_stand_berekenen(uuid,date,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.voorraad_bewegingen_lezen(text),public.voorraad_stand_berekenen(uuid,date,uuid) TO authenticated,service_role;
REVOKE ALL ON FUNCTION public.voorraad_telling_valideren(),public.voorraad_relatie_valideren() FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.v_voorraad_bewegingen,public.v_voorraad_stand TO authenticated,service_role;
COMMENT ON FUNCTION public.voorraad_daggrens(date,text) IS 'Voor opening ontvangst/correctie/kassa >= teldatum; na sluit > teldatum; zelfde periodegrens.';
COMMENT ON FUNCTION public.voorraad_teldeadline(timestamptz) IS 'Laatste woensdag 06:00 Europe/Amsterdam; gesloten dagen verplaatsen deadline niet.';
COMMENT ON FUNCTION public.voorraad_hertellen_nodig(numeric,numeric) IS 'Hertellen bij abs(totaal-stand)>greatest(abs(stand)*0.20,2); grens zelf toegestaan.';
COMMENT ON FUNCTION public.voorraad_bewegingen_lezen(text) IS 'Afgeschermde definer: eigen vestiging, alleen proefbewegingen zonder prijzen/omzet; refs hist/bord/kassa/corr; onduidelijk is NULL.';
COMMENT ON FUNCTION public.voorraad_stand_berekenen(uuid,date,uuid) IS 'Eigen vestiging: laatste betrouwbare telling+ontvangst+correcties-kassa-kassa*opslag_pct/100; NULL zonder anker.';
COMMENT ON FUNCTION public.voorraad_telling_valideren() IS 'Alleen nieuwe tellingtrigger: server berekent totaal/snapshot/betrouwbaarheid/identiteit; tweede blinde telling leidend.';
COMMENT ON FUNCTION public.voorraad_relatie_valideren() IS 'Alleen nieuwe logs/voorstellen: relatie moet bij vestiging horen; owner beoordeling past geen instelling toe.';
COMMENT ON VIEW public.v_voorraad_bewegingen IS 'security_invoker; beperkte proefbewegingen; historische besteldatum is ontvangstbenadering.';
COMMENT ON VIEW public.v_voorraad_stand IS 'security_invoker; ochtend >= datum/sluit > datum; voorraad onbekend zonder betrouwbare telling; negatief niet afgekapt.';